IF  EXISTS(SELECT * FROM sys.objects WHERE type = 'P' AND name ='USP_GETNEWUSERFOROTHERSYSTEM')
BEGIN
		DROP PROCEDURE [dbo].[USP_GETNEWUSERFOROTHERSYSTEM]
END
GO



CREATE PROC [dbo].[USP_GETNEWUSERFOROTHERSYSTEM]
(
@ADEndpointSystemId bigint,
@endpointsystemId bigint
)
AS
BEGIN

select DI_INH_Permission.Id,Name,item as ADGroup,Description into #tblPermission from DI_INH_Permission CROSS APPLY dbo.Split(ADGroups,',') where EndPointSystemId = @endpointsystemId AND IsActive = 1 AND LEN(item)>0

select AccountReconcilationId,Entitlement into #entitlement from DI_M_EntitlementReconcilation where EndpointSystemId = @ADEndpointSystemId and IsDeleted = 0 and Entitlement in(select ADGroup from #tblPermission)


select B.Id as PermissionId,B.Name as Permission,B.Description,E.FullName,E.EmployeeId,E.UserId,E.FirstName,E.LastName,E.AccountName,E.AccountType,E.MappingType,E.Entitlement from 
(
	select A.FullName, E.Entitlement,A.AccountType,MappingType,A.AccountName,U.EmployeeId,A.UserId,U.FirstName,U.LastName from #entitlement E
	join DI_M_AccountReconcilation A on E.AccountReconcilationId = A.Id
	LEFT Join DI_M_User U on A.UserId = U.Id
	where A.EndpointSystemId = @ADEndpointSystemId and A.IsDeleted = 0 AND A.AccountType in(1,2,3,4)
) E 
join 
(
	select Id,Name,ADGroup,Description from #tblPermission
)as B on E.Entitlement = B.ADGroup  AND E.AccountName NOT IN(Select UserName from DI_INH_UserInfo where EndpointSystemId = @endpointsystemId and IsDeleted = 0) order by E.AccountName

END
GO


IF EXISTS(SELECT * FROM sys.objects WHERE type = 'P' AND name ='USP_GETOtherSystemUserADGroupNotExists')
BEGIN
		DROP PROCEDURE [dbo].[USP_GETOtherSystemUserADGroupNotExists]
END
GO


GO
/*
NAME		:	USP_GETOtherSystemUserADGroupNotExists
description	:	Used to fetch list of account
exec USP_GETOtherSystemUserADGroupNotExists 'hocksoonpek',55,3
*/
CREATE PROC [dbo].[USP_GETOtherSystemUserADGroupNotExists]
(
@AccountName nvarchar(512),
@EndpointSystemId bigint,
@ADEndpointId bigint
)
AS
BEGIN

	SELECT B.AccountName as UserName,B.Entitlement as Permission, B.AccountReconcilationId , D.Entitlement,B.DisplayName,B.AccountType into #tbltemp
	FROM 
	(
		SELECT DI_INH_Permission.Id,Name,item as value FROM DI_INH_Permission CROSS APPLY dbo.Split(ADGroups,',') WHERE LEN(item)>0 and EndpointSystemId = @EndpointSystemId AND IsActive = 1
	) as A INNER JOIN
	(
		SELECT A.Id as AccountReconcilationId, A.AccountName,E.Entitlement,U.DisplayName,A.AccountType FROM DI_M_AccountReconcilation A INNER JOIN DI_M_EntitlementReconcilation E on A.Id = E.AccountReconcilationId
		LEFT JOIN DI_M_User U on A.UserId = U.Id
		WHERE A.EndpointSystemId = @EndpointSystemId AND A.IsDeleted = 0 AND e.IsDeleted = 0 AND A.AccountName = @AccountName AND A.AccountName IN(SELECT AccountName FROM DI_M_AccountReconcilation WHERE EndpointSystemId  = @ADEndpointId and AccountName=@AccountName AND IsDeleted = 0)
	)as B on A.Name = B.Entitlement
	LEFT JOIN 
	(
		SELECT EE.Entitlement FROM DI_M_AccountReconcilation AU JOIN DI_M_EntitlementReconcilation EE on AU.Id = EE.AccountReconcilationId
		WHERE AU.EndpointSystemId= @ADEndpointId AND EE.EndpointSystemId = @ADEndpointId AND AU.IsDeleted = 0 AND EE.IsDeleted = 0 AND Au.AccountName = @AccountName
	)as D on A.value = D.Entitlement

	SELECT UserName,Permission,AccountReconcilationId,DisplayName FROM #tbltemp WHERE Entitlement IS NULL and Permission NOT IN(SELECT Permission FROM #tbltemp WHERE Entitlement IS NOT NULL)
	

END
GO
