GO

/*
exec USP_OTHERSYSTEM_ADDMISSINGPERMISSION 'CHRISTINATAN',55,3
*/
CREATE PROC [dbo].[USP_OTHERSYSTEM_ADDMISSINGPERMISSION]
(
@AccountName nvarchar(512),
@EndpointSystemId bigint,
@ADEndpointId bigint
)
AS
BEGIN
		Declare @AccountReconcilationId bigint
		Declare @endpointUserId bigint
		SELECT @AccountReconcilationId = Id,@endpointUserId=EndpointUserId FROM DI_M_AccountReconcilation WHERE EndpointSystemId = @EndpointSystemId  AND IsDeleted = 0 AND AccountName = @AccountName

		SELECT @AccountReconcilationId as AccountReconcilationId,@AccountName as AccountName, A.Name as Permission,A.Name as Entitlement,B.AccountType,B.MappingType,A.Description,EMP.DisplayName as FullName,EMP.EmployeeId,B.UserId,EMP.FirstName,EMP.LastName from 
		
		(SELECT A.Id as AccountReconcilationId, A.AccountName,E.Entitlement FROM DI_M_AccountReconcilation A INNER JOIN DI_M_EntitlementReconcilation E on A.Id = E.AccountReconcilationId
		WHERE A.EndpointSystemId = @EndpointSystemId AND A.IsDeleted = 0 AND e.IsDeleted = 0 AND A.AccountName = @AccountName AND A.AccountName IN(select AccountName from DI_M_AccountReconcilation WHERE EndpointSystemId  = @ADEndpointId and AccountName=@AccountName AND IsDeleted = 0)
		) as U
		Right Join 
		(SELECT DI_INH_Permission.Id,Name,Item as value,Description FROM DI_INH_Permission CROSS APPLY dbo.Split(ADGroups,',') WHERE LEN(Item)>0 and EndpointSystemId = @EndpointSystemId AND IsActive = 1)as A
		on U.Entitlement = A.Name
		join (
		SELECT EE.Entitlement,AU.UserId,AU.AccountType,AU.MappingType FROM DI_M_AccountReconcilation AU JOIN DI_M_EntitlementReconcilation EE on AU.Id = EE.AccountReconcilationId
		WHERE AU.EndpointSystemId= @ADEndpointId AND EE.EndpointSystemId = @ADEndpointId AND AU.IsDeleted = 0 AND EE.IsDeleted = 0 AND Au.AccountName = @AccountName
		) as B on A.value = B.Entitlement
		LEFT JOIN DI_M_USER EMP on B.UserId = EMP.Id
		WHERE U.AccountReconcilationId IS NULL

END
GO

IF  EXISTS(SELECT * FROM sys.objects WHERE type = 'P' AND name ='USP_UPDATEOTHERSYSTEM_ACCOUNTYYPEFROMAD')
BEGIN
		DROP PROCEDURE [dbo].[USP_UPDATEOTHERSYSTEM_ACCOUNTYYPEFROMAD]
END

GO
CREATE PROC [dbo].[USP_UPDATEOTHERSYSTEM_ACCOUNTYYPEFROMAD]
(
@endpointid BIGINT,
@ADEndpointId BIGINT
)
AS
BEGIN

		SET NOCOUNT ON;

		DECLARE @count BIGINT
		DECLARE @accountReconId BIGINT
		DECLARE @UserId BIGINT

		DECLARE @accountType TINYINT = 0
		DECLARE @mappingType TINYINT = 0
		DECLARE @OffboardingAccountAction TINYINT = 0

		DECLARE @INH_accountType TINYINT = 0
		DECLARE @INH_mappingType TINYINT = 0
		DECLARE @INH_OffboardingAccountAction TINYINT = 0

		DECLARE @accountName nvarchar(max)=''
		DECLARE @EmpId nvarchar(256)=''
		DECLARE @EndpointUserId BIGINT

		IF EXISTS(SELECT 1 FROM DI_M_EndpointSystem WHERE EndpointSystemTypeId = 9 AND ApplicationType = 21 AND Id = @endpointid AND CanAutomate = 1)
		BEGIN

				IF EXISTS(SELECT 1 FROM DI_M_EndpointSystem WHERE ApplicationType = 1 AND Id = @ADEndpointId)
				BEGIN

						SELECT  IDENTITY(INT,1,1) AS pid,CONVERT(BIGINT, Id)AS AccountReconId,AccountName,MappingType,AccountType, OffboardingAccountAction,EndpointUserId INTO #tbltemp FROM DI_M_AccountReconcilation 
						WHERE EndpointSystemId = @endpointid and IsDeleted = 0 AND AccountType IN(2,3) order by LastModifiedDate desc
						SET @count = @@ROWCOUNT

						IF EXISTS(SELECT 1 FROM DI_M_EndpointSystem WHERE EndpointSystemTypeId = 9 AND ApplicationType = 21 AND Id = @endpointid AND CanAutomate = 1 and SupportSecondaryAccount = 1)
						BEGIN
								INSERT INTO #tbltemp(AccountReconId, AccountName,MappingType,AccountType,OffboardingAccountAction,EndpointUserId)
								SELECT  CONVERT(BIGINT, Id)AS AccountReconId,AccountName,MappingType,AccountType, OffboardingAccountAction,EndpointUserId FROM DI_M_AccountReconcilation 
								WHERE EndpointSystemId = @endpointid and IsDeleted = 0 AND AccountType IN(4) order by LastModifiedDate desc
								
						END

						SELECT  Id,AccountName,MappingType,AccountType,OffboardingAccountAction,UserId INTO #tblADAcocunts 
						FROM DI_M_AccountReconcilation WHERE EndpointSystemId = @ADEndpointId and IsDeleted = 0 AND AccountName IN(SELECT AccountName FROM #tbltemp) order by LastModifiedDate desc


						DECLARE @lastmodifieddate DATETIME = GETDATE()

						WHILE @count > 0
						BEGIN
								SET @mappingType = 0
								SET @accountType = 0

								SET @INH_accountType = 0
								SET @INH_mappingType = 0	

								SET @INH_OffboardingAccountAction = 1
								SET @OffboardingAccountAction = 1

								SELECT @accountName = AccountName,@accountReconId = AccountReconId, @INH_accountType = AccountType, @INH_mappingType = MappingType  ,@INH_OffboardingAccountAction = OffboardingAccountAction,
								@EndpointUserId = EndpointUserId
								FROM #tbltemp WHERE pid = @count

								SELECT @mappingType = MappingType,@accountType = AccountType ,@OffboardingAccountAction = OffboardingAccountAction, @UserId = UserId
								FROM #tblADAcocunts WHERE AccountName = @accountName

								IF(LEN(ISNULL(@accountName,''))> 0 AND ISNULL(@mappingType,'')<>'' AND ISNULL(@accountType,'')<>'' AND ISNULL(@accountReconId,'')<>'' and @accountReconId > 0 AND ISNULL(@UserId,0)> 0)
								BEGIN
										
										Update DI_M_AccountReconcilation SET UserId = @UserId, AccountType = @accountType , MappingType = @mappingType,OffboardingAccountAction = @OffboardingAccountAction ,LastModifiedDate = @lastmodifieddate WHERE Id = @accountReconId AND EndpointSystemId = @endpointid 
										
										
										SET @EmpId=''
										SELECT @EmpId = EmployeeId from DI_M_User where Id = @UserId
										IF (LEN(ISNULL(@EmpId,''))> 0 AND @EndpointUserId > 0)
										BEGIN
												Update DI_INH_UserInfo Set EmployeeId = @EmpId WHERE  EndpointSystemId = @endpointid AND Id =@EndpointUserId AND UserName = @accountName
										END
								END

								SET @count = @count - 1;
		
						END

				END

		END
END
GO


